[Test]public void DefaultV2CalibrationSchedule_IsExactFullGridGolden(){double y=ProductionExecutionOptions.YearSeconds,d=45*ProductionExecutionOptions.DaySeconds,r=ProductionExecutionOptions.CalibratedProductionRateM3PerSecond;var o=new ProductionExecutionOptions();ProductionScheduleSegment[] expected=[new(0,d,false,"Rate",-r,1e6,.1e6,50e6,r),new(d,y-d,true,"Rate",0,1e6,.1e6,50e6,r),new(y,d,false,"Bhp",0,1e6,.1e6,50e6,r),new(y+d,2*y-d,true,"Rate",0,1e6,.1e6,50e6,r),new(3*y,d,false,"Rate",-r,1e6,.1e6,50e6,r),new(3*y+d,2*y-d,true,"Rate",0,1e6,.1e6,50e6,r)];Assert.Multiple(()=>{Assert.That(o.CalibrationVersion,Is.EqualTo("production-calibration-default-v2"));Assert.That(o.ModelVersion,Is.EqualTo("completion-production-v1"));Assert.That(r,Is.EqualTo(8e-9));Assert.That(o.InitialTimeStepSeconds,Is.EqualTo(d));Assert.That(o.Solver.MaximumTimeStepSeconds,Is.EqualTo(y));Assert.That(o.Solver.CgRelativeTolerance,Is.EqualTo(1e-6));Assert.That(o.Solver.MaximumSamplesPerWell,Is.EqualTo(120));Assert.That(o.Schedule,Is.EqualTo(expected));});}
