[TestFixture,NonParallelizable]public sealed class ProductionTransportTests{[Test]public void ProductionClient_HasDedicatedFiveMinutePipeline_WhileOtherClientsKeepDefaults(){using var f=new ApiFactory();_ = f.CreateInternalClient();var options=f.Services.GetRequiredService<IOptionsMonitor<HttpStandardResilienceOptions>>();string production=nameof(ReservoirProductionClient)+"-standard",analysis=nameof(AnalysisVerificationClient)+"-standard";HttpStandardResilienceOptions p=options.Get(production),a=options.Get(analysis);HttpClient client=f.Services.GetRequiredService<IHttpClientFactory>().CreateClient(nameof(ReservoirProductionClient));Assert.Multiple(()=>{Assert.That(p.TotalRequestTimeout.Timeout,Is.EqualTo(TimeSpan.FromMinutes(5)));Assert.That(p.AttemptTimeout.Timeout,Is.EqualTo(TimeSpan.FromMinutes(5)));Assert.That(p.Retry.MaxRetryAttempts,Is.EqualTo(1));Assert.That(client.Timeout,Is.EqualTo(Timeout.InfiniteTimeSpan));Assert.That(a.TotalRequestTimeout.Timeout,Is.EqualTo(TimeSpan.FromSeconds(30)));Assert.That(a.AttemptTimeout.Timeout,Is.EqualTo(TimeSpan.FromSeconds(10)));});}}
