arameters.AddWithValue("$hash",TestData.HashA);immutable.Parameters.AddWithValue("$run",run.RunId);Assert.ThrowsAsync<SqliteException>(async()=>await immutable.ExecuteNonQueryAsync());}await using(var tamper=db.CreateCommand()){tamper.CommandText="DROP TRIGGER TR_ProductionSeries_NoUpdate;UPDATE ProductionSeries SET OptionsHash=$hash WHERE RunId=$run;DROP TRIGGER TR_ProductionTruth_NoUpdate;UPDATE ProductionTruthArtifacts SET RequestHash=$hash WHERE RunId=$run";tamper.Parameters.AddWithValue("$hash",TestData.HashA);tamper.Parameters.AddWithValue("$run",run.RunId);await tamper.ExecuteNonQueryAsync();}Assert.Multiple(()=>{Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restart.GetProductionSeriesAsync(run.RunId));Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restart.GetProductionTruthAsync(run.RunId));});}
[Test]public async Task UnavailableProduction_ResumesWithoutDuplicateArtifacts(){int calls=0;Func<HttpRequestMessage,HttpResponseMessage> responder=_=>calls++==0?TestData.Json(HttpStatusCode.ServiceUnavailable,new{}):ProductionClientTests.Response("ok","completion-binding-1");await using var f=new ApiFactory(productionResponder:responder);using var c=f.CreateInternalClient();RunResponse run=await CreateAndApprove(c);await Wait(c,run.RunId,x=>x.Status==RunStatus.AwaitingDependency&&x.CurrentStage==RunStageKind.S7RunProduction);using var resume=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/resume");resume.Headers.Add("Idempotency-Key","resume-production");Assert.That((await c.SendAsync(resume)).StatusCode,Is.EqualTo(HttpStatusCode.Accepted));await Wait(c,run.RunId,x=>x.Status==RunStatus.ReadyToReveal&&x.CurrentStage==RunStageKind.S7RunProduction);await using var db=new SqliteConnection($"Data Source={f.DatabasePath}");await db.OpenAsync();await using var count=db.CreateCommand();count.CommandText="SELECT (SELECT COUNT(*) FROM ProductionTruthArtifacts WHERE RunId=$run),(SELECT COUNT(*) FROM ProductionSeries WHERE RunId=$run)";count.Parameters.AddWithValue("$run",run.RunId);await using var reader=await count.ExecuteReaderAsync();await reader.ReadAsync();Assert.Multiple(()=>{Assert.That(reader.GetInt32(0),Is.EqualTo(1));Assert.That(reader.GetInt32(1),Is.EqualTo(1));Assert.That(calls,Is.EqualTo(2));});}[TestCase("unavailable",RunStatus.AwaitingDependency)][TestCase("malformed",RunStatus.Failed)]public async Task UpstreamFailuresRemainAtS7AndDoNotPublish(string mode,RunStatus expected){Func<HttpRequestMessage,HttpResponseMessage> responder=_=>mode=="unavailable"?TestData.Json(HttpStatusCode.ServiceUnavailable,new{}):new(HttpStatusCode.OK){Content=new StringContent("{")};await using var f=new ApiFactory(productionResponder:responder);using var c=f.CreateInternalClient();RunResponse run=await CreateAndApprove(c);RunResponse final=await Wait(c,run.RunId,x=>x.Status==expected&&x.CurrentStage==RunStageKind.S7RunProduction);Assert.That(final.CurrentStage,Is.EqualTo(RunStageKind.S7RunProduction));Assert.That(await f.Services.GetRequiredService<DrillingOperationsStore>().GetSideEffectCountsAsync(run.RunId),Is.EqualTo((0,0)));}
static async Task<RunResponse>CreateAndApprove(HttpClient c){using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());(await c.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());var response=await c.SendAsync(create);var run=JsonSerializer.Deserialize<RunResponse>(await response.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;await Wait(c,run.RunId,x=>x.Status==RunStatus.AwaitingApproval);using var approve=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");approve.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());approve.Headers.Add("X-DrillSim-Human-Actor","production-test");(await c.SendAsync(approve)).EnsureSuccessStatusCode();return run;}static async Task<RunResponse>Wait(HttpClient c,string id,Func<RunResponse,bool> done){for(int i=0;i<400;i++){var x=(await c.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{id}",CanonicalJson.SerializerOptions))!;if(done(x))return x;await Task.Delay(20);}throw new AssertionException("Run timeout.");}}














